code_sketch:
indirect enum Expr {
    case num(Int)
    case add(Expr, Expr)
    case neg(Expr)
}
func eval(_ e: Expr, _ ctx: inout Context) throws -> Int {
    switch e {
    case .num(let v): return v
    case .add(let l, let r): return try eval(l, &ctx) + eval(r, &ctx)
    case .neg(let x): return -(try eval(x, &ctx))
    }
}

