protocol Expression { func interpret(_ ctx: inout Context) throws -> Int }
struct Num: Expression {
    let value: Int
    func interpret(_ ctx: inout Context) throws -> Int { value }
}
struct Add: Expression {
    let left: Expression, right: Expression
    func interpret(_ ctx: inout Context) throws -> Int {
        try left.interpret(&ctx) + right.interpret(&ctx)
    }
}
